CREATE SCHEMA IF NOT EXISTS izicybercafe;
SET search_path = izicybercafe, pg_catalog;
CREATE TABLE users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE cafes(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner_id INTEGER UNIQUE REFERENCES users(id),name TEXT NOT NULL,location TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE services(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cafe_id INTEGER REFERENCES cafes(id),name TEXT NOT NULL,price INTEGER NOT NULL, fulfilment_mode TEXT NOT NULL DEFAULT 'digital');
CREATE TABLE orders(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id INTEGER REFERENCES users(id),cafe_id INTEGER REFERENCES cafes(id),service_id INTEGER REFERENCES services(id),instructions TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'requested',created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')), fulfilment_mode TEXT NOT NULL DEFAULT 'digital');
CREATE TABLE audit(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor INTEGER REFERENCES users(id),action TEXT NOT NULL,target INTEGER,created TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE order_files(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),uploader INTEGER NOT NULL REFERENCES users(id),name TEXT NOT NULL,type TEXT NOT NULL,bytes BYTEA NOT NULL,created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE order_messages(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),sender INTEGER NOT NULL REFERENCES users(id),message TEXT NOT NULL,created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE quotes(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),amount INTEGER NOT NULL,scope TEXT NOT NULL,turnaround TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE payment_attempts(sequence_id BIGINT GENERATED ALWAYS AS IDENTITY,id TEXT PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),amount INTEGER NOT NULL,phone TEXT NOT NULL,environment TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'initiating',checkout TEXT UNIQUE,merchant TEXT,last_checked BIGINT NOT NULL DEFAULT 0,created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE payments(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER UNIQUE NOT NULL REFERENCES orders(id),attempt_id TEXT UNIQUE NOT NULL REFERENCES payment_attempts(id),amount INTEGER NOT NULL,checkout TEXT UNIQUE NOT NULL,environment TEXT NOT NULL,created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE deliveries(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),file_id INTEGER UNIQUE NOT NULL REFERENCES order_files(id),note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE print_options(order_id INTEGER PRIMARY KEY REFERENCES orders(id),file_id INTEGER REFERENCES order_files(id),copies INTEGER NOT NULL,paper TEXT NOT NULL,color TEXT NOT NULL,sides TEXT NOT NULL);
CREATE TABLE printers(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cafe_id INTEGER NOT NULL REFERENCES cafes(id),name TEXT NOT NULL,environment TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,color INTEGER NOT NULL,duplex INTEGER NOT NULL,last_seen BIGINT);
CREATE TABLE print_jobs(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id INTEGER UNIQUE NOT NULL REFERENCES orders(id),file_id INTEGER NOT NULL REFERENCES order_files(id),cafe_id INTEGER NOT NULL REFERENCES cafes(id),environment TEXT NOT NULL,copies INTEGER NOT NULL,paper TEXT NOT NULL,color TEXT NOT NULL,sides TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',printer_id INTEGER REFERENCES printers(id),claim_token TEXT,attempt INTEGER NOT NULL DEFAULT 0,spool_id TEXT,created TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX order_files_order ON order_files(order_id);
CREATE INDEX order_messages_order ON order_messages(order_id);
CREATE INDEX quotes_order ON quotes(order_id);
CREATE UNIQUE INDEX one_pending_quote ON quotes(order_id) WHERE status='pending';
CREATE UNIQUE INDEX one_active_payment ON payment_attempts(order_id) WHERE status IN ('initiating','pending','review','paid');
CREATE INDEX deliveries_order ON deliveries(order_id);
CREATE INDEX print_jobs_queue ON print_jobs(cafe_id,status,id);
REVOKE ALL ON SCHEMA izicybercafe FROM PUBLIC,anon,authenticated;
ALTER TABLE izicybercafe.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.cafes ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.services ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.order_files ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.order_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.quotes ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.payment_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.print_options ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.printers ENABLE ROW LEVEL SECURITY;
ALTER TABLE izicybercafe.print_jobs ENABLE ROW LEVEL SECURITY;

CREATE INDEX orders_customer ON izicybercafe.orders(customer_id,id);
CREATE INDEX orders_cafe ON izicybercafe.orders(cafe_id,id);
CREATE INDEX sessions_user ON izicybercafe.sessions(user_id);
CREATE INDEX services_cafe ON izicybercafe.services(cafe_id);
